import re
from typing import Dict, Optional

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    sections: Dict[str, Dict[str, str]] = {}
    current_section: Optional[str] = None
    default_section: Dict[str, str] = {}
    lines = text.splitlines()
    i = 0

    while i < len(lines):
        line = lines[i].strip()

        if not line or line.startswith((';', '#')):
            i += 1
            continue

        match = re.match(r'\s*\[([^]]+)\]', line)
        if match:
            current_section = match.group(1).lower()
            if current_section == 'default':
                default_section = sections.pop('default', {})
            else:
                sections[current_section] = default_section.copy()
            i += 1
            continue

        match = re.match(r'\s*([^=:#;]+)\s*(=|:)\s*(.*)', line)
        if not match:
            raise ValueError(f"Malformed line: {line!r}")

        key, sep, value = match.groups()
        key = key.lower().strip()

        if current_section is None:
            raise ValueError(f"No section for key: {key!r}")

        if key in sections[current_section]:
            i += 1
            continue

        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        else:
            value = value.strip()

        sections[current_section][key] = value

        while i + 1 < len(lines) and lines[i + 1].strip() and lines[i + 1].strip()[0].isspace():
            value += '\n' + lines[i + 1].strip()
            i += 1

        i += 1

    return sections
