import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key, value):
        now = self.clock()
        if key in self.cache:
            self.cache.move_to_end(key)
            self.cache[key] = (now + self.ttl, value)
        else:
            if len(self.cache) >= self.capacity:
                self._evict(now)
            self.cache[key] = (now + self.ttl, value)

    def get(self, key, default=None):
        now = self.clock()
        if key in self.cache and self.cache[key][0] > now:
            self.cache.move_to_end(key)
            return self.cache[key][1]
        else:
            self.stats["expirations"] += 1
            self.stats["misses"] += 1
            del self.cache[key]
            return default

    def __len__(self):
        now = self.clock()
        return sum(1 for k, v in self.cache.items() if v[0] > now)

    def stats(self):
        return self.stats

    def _evict(self, now):
        while self.cache:
            key = next(iter(self.cache))
            if self.cache[key][0] > now:
                break
            self.stats["evictions"] += 1
            del self.cache[key]
