from decimal import Decimal, InvalidOperation
from collections import defaultdict

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customers = defaultdict(Decimal)
    for row in rows:
        name = row.get("customer", "").strip()
        if not name:
            continue
        try:
            amount = Decimal(row["amount"].replace(",", ""))
        except InvalidOperation:
            continue
        customers[name.lower()] += amount
    return sorted(customers.items(), key=lambda x: (-x[1], x[0]))[:n]
